$$\begin{array}{l}
  {y_{p}^{\prime}(x) = A\cos x - Ax\sin x + B\sin x + Bx\cos x} \\
  {y_{p}^{''}(x) = - 2A\sin x - Ax\cos x + 2B\cos x - Bx\sin x}
  \end{array}$$

$$\begin{array}{l}
  {y_{p}(x) = - \cos x\sin x + \left\lbrack {\sin x - \ln\left( {\sec x + \tan x} \right)} \right\rbrack\cos x} \\
  {\phantom{y_{p}(x)} = - \cos x\ln\left( {\sec x + \tan x} \right)}
  \end{array}$$
